from algo_service.sdk.decorators import algo_meta


@algo_meta(
    zh_name="中文算法名称",
    zh_description="说明算法用途、输入输出和适用场景。",
    zh_tags=["分类", "业务标签"],
    version="1.0.0",
)
def algorithm_name(data: list, threshold: float = 0.5) -> dict:
    return {"count": len(data), "threshold": threshold}

def validate_required(value, name: str):
    if value is None:
        raise ValueError(f"{name} must not be None")
    if isinstance(value, (list, dict, str)) and not value:
        raise ValueError(f"{name} must not be empty")
    return value


def validate_range(value: float, name: str, low: float, high: float) -> float:
    number = float(value)
    if number < low or number > high:
        raise ValueError(f"{name} must be between {low} and {high}")
    return number

def standard_result(success: bool, data=None, message: str = "", **meta) -> dict:
    return {
        "success": success,
        "data": data,
        "message": message,
        "meta": meta,
    }
